BEGIN;
CREATE TABLE IF NOT EXISTS forge_capacity_pools (resource text PRIMARY KEY CHECK (resource IN ('api_requests','workflow_jobs','provider_executions','media_cpu','runner_executions','storage_operations')),capacity bigint NOT NULL CHECK (capacity>0),reserved bigint NOT NULL DEFAULT 0 CHECK(reserved>=0),in_use bigint NOT NULL DEFAULT 0 CHECK(in_use>=0),queue_soft_limit bigint NOT NULL DEFAULT 100 CHECK(queue_soft_limit>=0),queue_hard_limit bigint NOT NULL DEFAULT 500 CHECK(queue_hard_limit>=queue_soft_limit),latency_soft_ms bigint NOT NULL DEFAULT 1000 CHECK(latency_soft_ms>=0),latency_hard_ms bigint NOT NULL DEFAULT 5000 CHECK(latency_hard_ms>=latency_soft_ms),utilization_soft numeric(5,4) NOT NULL DEFAULT .75 CHECK(utilization_soft BETWEEN 0 AND 1),utilization_hard numeric(5,4) NOT NULL DEFAULT .90 CHECK(utilization_hard BETWEEN utilization_soft AND 1),hysteresis_seconds integer NOT NULL DEFAULT 30 CHECK(hysteresis_seconds BETWEEN 1 AND 3600),drain boolean NOT NULL DEFAULT false,emergency_shed boolean NOT NULL DEFAULT false,priority_floor integer NOT NULL DEFAULT 0,version bigint NOT NULL DEFAULT 1,updated_by text NOT NULL DEFAULT 'system',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forge_capacity_workers (worker_id text PRIMARY KEY,worker_type text NOT NULL,capacity_class text NOT NULL DEFAULT 'default',capacity bigint NOT NULL CHECK(capacity>0),active_claims bigint NOT NULL DEFAULT 0 CHECK(active_claims>=0),state text NOT NULL DEFAULT 'READY' CHECK(state IN ('READY','DRAINING','DRAINED','LOST')),last_heartbeat_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz NOT NULL DEFAULT now(),release_epoch text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_capacity_workers_heartbeat_idx ON forge_capacity_workers(last_heartbeat_at);
CREATE TABLE IF NOT EXISTS forge_capacity_claims (id text PRIMARY KEY,resource text NOT NULL REFERENCES forge_capacity_pools(resource) ON DELETE RESTRICT,worker_id text NOT NULL REFERENCES forge_capacity_workers(worker_id) ON DELETE RESTRICT,tenant_id text REFERENCES tenants(id) ON DELETE RESTRICT,project_id text REFERENCES projects(id) ON DELETE RESTRICT,job_id text REFERENCES forge_jobs(id) ON DELETE RESTRICT,priority integer NOT NULL DEFAULT 0,units bigint NOT NULL CHECK(units>0),status text NOT NULL DEFAULT 'HELD' CHECK(status IN ('HELD','RELEASED','EXPIRED','SETTLED')),idempotency_key text NOT NULL UNIQUE,lease_until timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),released_at timestamptz,metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX IF NOT EXISTS forge_capacity_claims_active_idx ON forge_capacity_claims(resource,status,lease_until);
CREATE INDEX IF NOT EXISTS forge_capacity_claims_tenant_idx ON forge_capacity_claims(tenant_id,status,priority,created_at);
CREATE TABLE IF NOT EXISTS forge_capacity_reservations (id text PRIMARY KEY,resource text NOT NULL REFERENCES forge_capacity_pools(resource) ON DELETE RESTRICT,tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,project_id text REFERENCES projects(id) ON DELETE RESTRICT,units bigint NOT NULL CHECK(units>0),priority integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'HELD' CHECK(status IN ('HELD','RELEASED','EXPIRED','CONSUMED')),expires_at timestamptz NOT NULL,idempotency_key text NOT NULL UNIQUE,actor text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_capacity_reservations_active_idx ON forge_capacity_reservations(resource,status,expires_at);
CREATE TABLE IF NOT EXISTS forge_capacity_signals (resource text NOT NULL REFERENCES forge_capacity_pools(resource) ON DELETE CASCADE,observed_at timestamptz NOT NULL DEFAULT clock_timestamp(),queue_depth bigint NOT NULL DEFAULT 0,p95_latency_ms numeric(20,3) NOT NULL DEFAULT 0,utilization numeric(8,5) NOT NULL DEFAULT 0,db_pool_wait_ms numeric(20,3) NOT NULL DEFAULT 0,signal_state text NOT NULL CHECK(signal_state IN ('NORMAL','SOFT','HARD','DRAINING','SHED')),metadata jsonb NOT NULL DEFAULT '{}'::jsonb,PRIMARY KEY(resource,observed_at));
CREATE INDEX IF NOT EXISTS forge_capacity_signals_recent_idx ON forge_capacity_signals(resource,observed_at DESC);
CREATE TABLE IF NOT EXISTS forge_capacity_controls (key text PRIMARY KEY,value jsonb NOT NULL,version bigint NOT NULL DEFAULT 1,updated_by text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forge_capacity_fairness (resource text NOT NULL REFERENCES forge_capacity_pools(resource) ON DELETE CASCADE,tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,weight numeric(12,4) NOT NULL DEFAULT 1 CHECK(weight>0 AND weight<=1000),served_units numeric(30,6) NOT NULL DEFAULT 0,last_served_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(resource,tenant_id));
CREATE INDEX IF NOT EXISTS forge_capacity_fairness_order_idx ON forge_capacity_fairness(resource,served_units,updated_at);
INSERT INTO forge_capacity_pools(resource,capacity) VALUES('api_requests',120),('workflow_jobs',8),('provider_executions',8),('media_cpu',4),('runner_executions',4),('storage_operations',32) ON CONFLICT(resource) DO NOTHING;
INSERT INTO forge_capacity_controls(key,value,updated_by) VALUES('maintenance','false'::jsonb,'migration-runner'),('emergency_shed','false'::jsonb,'migration-runner'),('heartbeat_timeout_seconds','90'::jsonb,'migration-runner'),('claim_lease_seconds','120'::jsonb,'migration-runner'),('retry_jitter_seconds','15'::jsonb,'migration-runner') ON CONFLICT(key) DO NOTHING;
COMMIT;
